import {TOPICS,FARMS,PLANTS,SHIPMENTS,initialIdea,ideaCase,ideaResult,stepIdea} from './idea-models.js?v=graficos-20261027b';
import {activation} from './math.js';
import {renderThreeScene} from './three-scenes.js?v=graficos-20261027b';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number(n).toLocaleString('es-CO',{maximumFractionDigits:d,minimumFractionDigits:d});
const colors=['#507b3c','#ac602d','#547d9f'];
const text=(x,y,label,extra='')=>`<text x="${x}" y="${y}" ${extra}>${esc(label)}</text>`;
const line=(x1,y1,x2,y2,extra='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${extra}/>`;
const svg=(label,body,height=360)=>`<svg viewBox="0 0 720 ${height}" class="idea-plot" role="group" aria-label="${esc(label)}">${body}</svg>`;
function axes({xmin=0,xmax=1,ymin=0,ymax=1,xlabel,ylabel,xticks,yticks,width=600,height=235,left=78,bottom=285}){
 const x=v=>left+(v-xmin)/(xmax-xmin)*width,y=v=>bottom-(v-ymin)/(ymax-ymin)*height;
 return {x,y,body:`${yticks.map(v=>line(left,y(v),left+width,y(v),'class="idea-gridline"')+text(left-13,y(v)+5,fmt(v,Number.isInteger(v)?0:1),'text-anchor="end"')).join('')}${xticks.map(v=>text(x(v),bottom+25,fmt(v,Number.isInteger(v)?0:1),'text-anchor="middle"')).join('')}${line(left,bottom-height,left,bottom)}${line(left,bottom,left+width,bottom)}${text(left+width/2,bottom+62,xlabel,'text-anchor="middle"')}${text(21,bottom-height/2,ylabel,`text-anchor="middle" transform="rotate(-90 21 ${bottom-height/2})"`)}`};
}
function wideTicks(min,max){const target=(max-min)/4,unit=10**Math.floor(Math.log10(target)),step=[1,2,5,10].map(v=>v*unit).find(v=>v>=target);return Array.from({length:8},(_,i)=>(Math.ceil(min/step)+i)*step).filter(v=>v<=max);}
const pick=(index,label,body,active)=>{const point=body.match(/<(?:circle|ellipse) cx="([^"]+)" cy="([^"]+)"/)||body.match(/<path d="M([\d.-]+) ([\d.-]+)/),hit=point?`<circle cx="${point[1]}" cy="${point[2]}" r="22" class="idea-hit"/>`:'';return `<g role="button" tabindex="0" data-pick="${index}" aria-label="${esc(label)}" aria-pressed="${active}" class="idea-pick ${active?'is-selected':''}"><title>${esc(label)}</title>${hit}${body}</g>`;};
const dot=(x,y,c,r=7)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const table=(headers,rows,caption)=>`<div class="idea-table-scroll" tabindex="0" role="region" aria-label="${esc(caption)}"><table><caption>${esc(caption)}</caption><thead><tr>${headers.map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const rowButton=(id,name,selected)=>`<button type="button" data-pick="${id}" aria-pressed="${String(id)===String(selected)}">${esc(name)}</button>`;
const metrics=items=>`<div class="idea-metrics">${items.map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>`;

// Explicaciones vinculadas al estado actual: una operación no sustituye su interpretación.
export function ideaTeaching(id,p,selected=0){
 const r=ideaResult(id,p),i=Number(selected)||0;
 let goal='',origin='',operation='',connection='';
 if(id==='prediction'){
  const f=FARMS[i]||FARMS[0],j=FARMS.indexOf(f),mx=FARMS.reduce((s,v)=>s+v.x,0)/FARMS.length,my=FARMS.reduce((s,v)=>s+v.y,0)/FARMS.length;
  goal='Distinguir una observación de una predicción y medir su error.';
  origin='Los seis pares fertilizante–rendimiento son inventados. La pendiente indica cuánto cambia la predicción por cada kg/ha; el intercepto es su valor en cero. Los controles eligen esos parámetros a mano; el botón Ajustar los calcula con las seis observaciones.';
  operation=`Finca ${f.name}: predicción = ${fmt(p.bias)} + ${fmt(p.slope,4)} × ${f.x} = ${fmt(r.predicted[j])} t/ha. Error absoluto = |${fmt(f.y)} − ${fmt(r.predicted[j])}| = ${fmt(r.errors[j])} t/ha. MAE = (${r.errors.map(v=>fmt(v)).join(' + ')}) / 6 = ${fmt(r.mae,3)} t/ha. Al ajustar: medias x̄ = ${fmt(mx)}, ȳ = ${fmt(my)}; pendiente = Σ[(x−x̄)(y−ȳ)] / Σ(x−x̄)² e intercepto = ȳ − pendiente × x̄.`;
  connection='MAE significa error absoluto medio; todos los errores pesan igual. El ajuste por mínimos cuadrados minimiza errores al cuadrado, una función distinta del MAE que mostramos. Menos error aquí no demuestra mejor desempeño con datos nuevos ni que el fertilizante cause ese rendimiento.';
 }else if(id==='alerts'){
  const v=r.rows[i]||r.rows[0];goal='Separar puntuación, umbral, decisión y realidad conocida.';
  origin='Las diez puntuaciones y las cuatro etiquetas de plaga se fijaron a mano. El umbral no sale de promediar puntuaciones: es una regla de decisión elegida según errores tolerables y capacidad de revisión. Aquí lo eliges con el control; no se entrena un modelo.';
  operation=`${v.name}: puntuación ${fmt(v.score)} ${v.alert?'≥':'<'} umbral ${fmt(p.threshold)} → ${v.alert?'alerta':'sin alerta'}. Su realidad es ${v.plague?'con plaga':'sana'}: ${ {tp:'detección correcta',fp:'falsa alerta',fn:'omisión',tn:'descarte correcto'}[v.kind]}. Alertas = ${r.tp} correctas + ${r.fp} falsas = ${r.tp+r.fp}; sin alerta = ${r.fn} omisiones + ${r.tn} descartes = ${r.fn+r.tn}. Capacidad elegida: 4 revisiones, no cuatro alertas garantizadas.`;
  connection=`Bajar el corte añade alertas; no cambia puntuaciones ni etiquetas. Sensibilidad = detectadas / todas las enfermas = ${r.tp}/4. Precisión de las alertas = ${r.tp}/${r.tp+r.fp}${r.tp+r.fp?'':' (sin alertas: no definida)'}. Elegir un corte real requiere validación y comprobarlo después con datos de prueba reservados. Una puntuación no es automáticamente una probabilidad calibrada.`;
 }else if(id==='missing'){
  goal='Completar una entrada sin confundir estimación con medición.';origin='A, C y D son tres registros simulados del mismo periodo, en milímetros. B no tiene medición. Elegimos la mediana como regla de imputación: ordenar los conocidos y tomar el centro. No incluimos a B como cero.';
  operation=`Orden: ${r.ordered.join(' ≤ ')} mm; posición central de tres valores = (3 + 1)/2 = 2 → B estimada = ${r.estimate} mm. Media = (${p.rainA} + ${p.rainC} + ${p.rainD})/3 = ${fmt(r.mean)} mm. La barra rayada y la línea horizontal muestran esa mediana; las barras verdes siguen siendo los registros conocidos.`;
  connection='La mediana suele resistir mejor un único valor extremo que la media, pero puede ser inadecuada si las estaciones no son comparables. En ML se ajusta el imputador solo con entrenamiento y se reutiliza en validación/prueba: recalcularlo con esos conjuntos filtraría información. Conservar una marca de dato ausente permite distinguir su origen.';
 }else if(id==='signal'){
  const x=p.signal;goal='Seguir una señal a través de una función de activación y comparar sus rangos.';origin='La señal es un número sin unidad física, elegido con el control. En una neurona suele ser z = Σ(peso × entrada) + sesgo; aquí empezamos directamente en z, sin aprender pesos. Las funciones son reglas matemáticas fijas.';
  operation=`Para z = ${fmt(x)}: ReLU = máx(0, ${fmt(x)}) = ${fmt(r.values[0].value,3)}; sigmoid = 1/(1 + e^(${fmt(-x)})) = ${fmt(r.values[1].value,3)}; tanh = (e^${fmt(x)} − e^(${fmt(-x)}))/(e^${fmt(x)} + e^(${fmt(-x)})) = ${fmt(r.values[2].value,3)}. e ≈ 2,718. La guía vertical conecta la misma entrada con los tres puntos; la altura es la salida.`;
  connection='ReLU devuelve cero o valores positivos sin límite superior; sigmoid queda entre 0 y 1 y tanh entre −1 y 1. Estas transformaciones no lineales permiten a las redes representar relaciones que una sola recta no expresa. Sigmoid puede producir una puntuación; un umbral es otra operación posterior para decidir una clase. Cambiar la función destacada solo cambia el énfasis visual.';
 }else if(id==='adjustment'){
  const n=Math.min(i,p.states.length-1),theta=p.states[n],rate=n?p.rates[n-1]:p.rate,prev=n?p.states[n-1]:theta,g=2*(prev-3);
  goal='Relacionar pérdida, gradiente y tamaño del siguiente ajuste.';origin='Elegimos la función artificial L(θ) = (θ − 3)², inicio θ = −2 y mínimo conocido en 3. θ (theta) es el parámetro ajustable; la tasa α es una decisión del experimento. No son datos ni resultados de una red entrenada.';
  operation=n?`Paso ${n} ya aplicado: gradiente = 2 × (${fmt(prev,3)} − 3) = ${fmt(g,3)}. Actualización θ nueva = θ previa − α × gradiente = ${fmt(prev,3)} − ${fmt(rate)} × (${fmt(g,3)}) = ${fmt(theta,3)}. Pérdida nueva = (${fmt(theta,3)} − 3)² = ${fmt(p.history[n],3)}.`:`Estado inicial: L(−2) = (−2 − 3)² = 25. Gradiente en −2 = 2 × (−2 − 3) = −10.`;
  operation+=r.next?` Siguiente paso, aún sin aplicar: desde θ actual ${fmt(p.theta,3)}, gradiente = ${fmt(r.next.gradient,3)}; con la tasa elegida α = ${fmt(p.rate)}, θ sería ${fmt(p.theta,3)} − ${fmt(p.rate)} × (${fmt(r.next.gradient,3)}) = ${fmt(r.next.theta,3)}, y la pérdida sería ${fmt(r.next.loss,3)}. El círculo punteado anticipa ese resultado; pulsa Dar un paso para incorporarlo al historial.`:' Se alcanzó el límite de quince pasos. Reinicia para comparar otra secuencia desde el mismo punto inicial.';
  connection='El gradiente es la pendiente de la pérdida, no la pérdida misma. Restarlo busca bajar: un gradiente negativo mueve θ hacia la derecha. Aquí θ nueva − 3 = (1 − 2α)(θ previa − 3): con 0 < α < 1 converge; α = 0,5 llega en un paso; α = 1 oscila y α > 1 puede alejarse. Esto es específico de esta parábola. La segunda gráfica permite comprobar si la pérdida bajó, no asumirlo.';
 }else if(id==='vision'){
  const objects=[[120,160,40,53],[300,145,48,60],[495,163,35,45]],j=Math.min(i,2),[x,y,rx,ry]=objects[j];
  goal='Elegir qué salida necesita una tarea visual y leer sus coordenadas.';origin='La imagen y sus tres frutos elípticos están dibujados. Las etiquetas, cajas y máscaras se construyen con geometría; no hay inferencia ni entrenamiento de un detector. Un píxel es una posición de la imagen; el origen (0,0) está arriba a la izquierda, x crece a la derecha e y hacia abajo.';
  operation=p.task==='classification'?'Salida: una etiqueta «imagen con frutos» para toda la imagen de 600 × 300 px. No contiene coordenadas ni un recuento individual.':`Fruto ${j+1}: centro (${x}, ${y}) px; radios (${rx}, ${ry}) px. Caja = [x−radio horizontal, y−radio vertical, x+radio horizontal, y+radio vertical] = [${x-rx}, ${y-ry}, ${x+rx}, ${y+ry}] px. Máscara: región interior de la elipse ((u−${x})/${rx})² + ((v−${y})/${ry})² ≤ 1; u y v son coordenadas de cada píxel. ${p.task==='detection'?'El rectángulo muestra los límites e incluye fondo.':'El color delimita el cuerpo; las esquinas de su caja quedan fuera.'}`;
  connection='Clasificación asigna una etiqueta global; detección combina categoría y localización; segmentación asigna regiones o etiquetas a píxeles. Aquí cada fruto conserva una máscara separada (instancias). El color de una máscara distingue objetos; no expresa confianza ni calidad. Cambiar la tarea no mejora un modelo: cambia el tipo de salida que se necesitaría evaluar.';
 }else if(id==='neighbors'){
  const v=r.ranked.find(v=>v.id===SHIPMENTS[i]?.id)||r.ranked[0],dx=v.xy[0]-r.query[0],dy=v.xy[1]-r.query[1];goal='Comprobar por qué un envío cuenta como vecino y cómo vota.';
  origin='Seis envíos simulados tienen distancia, carga y una categoría ya conocida. La consulta no tiene categoría conocida. k es un número de vecinos elegido por ti, no un peso aprendido. Estandarizar usa la media y desviación poblacional de esos seis históricos; no incluye la consulta.';
  operation=`Consulta: ${p.km} km y ${p.kg} kg. Envío ${v.id}: ${v.km} km y ${v.kg} kg. ${p.scaled==='yes'?`Cada coordenada se convierte con z = (valor − media)/desviación; medias = (${r.stats.map(s=>fmt(s.mean,3)).join('; ')}), desviaciones = (${r.stats.map(s=>fmt(s.sd,3)).join('; ')}). `:''}Distancia numérica = √[(${fmt(dx,3)})² + (${fmt(dy,3)})²] = ${fmt(v.distance,3)}. Votan ${r.selected.map(s=>s.id).join(', ')}: ${r.votes} Extendido y ${p.k-r.votes} Estándar → ${r.kind?'Extendido':'Estándar'}.`;
  connection='Sin escalar, las diferencias numéricas en kg suelen dominar la suma; el resultado mezcla unidades y no es una distancia geográfica. Con escala común cada diferencia se expresa en desviaciones, sin unidad. La desviación es √[Σ(valor−media)²/6]. Ordenar distancias decide quién vota; la mayoría decide la clase. k y escala se eligen con validación, y estandarizar no garantiza mejor predicción en cualquier problema.';
 }else{
  goal='Reconstruir una celda del mapa multiplicando una ventana por un filtro.';origin='Imagen binaria editable: 0 oscuro, 1 claro. Elegimos a mano un filtro 3 × 3: Horizontal resta fila superior de inferior; Promedio usa nueve pesos 1/9. No son pesos aprendidos. Cada celda de salida corresponde a una posición de la ventana, no a un píxel aislado.';
  operation=`Ventana: filas ${p.row+1}–${p.row+3}, columnas ${p.column+1}–${p.column+3}. Productos píxel × peso: ${r.products.flat().map(v=>fmt(v,3)).join(' + ')} = ${fmt(r.value,3)}. Paso 1 desplaza una celda, sin rellenar bordes: lado de salida = (5 − 3)/1 + 1 = 3 → mapa 3 × 3. La tabla muestra los nueve píxeles y pesos sin sustituirlos por una animación.`;
  connection='El mapa conserva la respuesta de cada ventana. En Horizontal, el signo indica dirección del cambio y el valor absoluto su intensidad; cero también puede significar cancelación, no necesariamente una imagen uniforme. Promedio suaviza y queda entre 0 y 1 aquí. Esta multiplicación sin voltear el filtro es correlación cruzada, habitualmente llamada convolución en CNN. Una CNN aprende filtros y añade activaciones y otras capas; este cálculo solo ilustra una operación.';
 }
 return `<section class="idea-learning" aria-label="Aprende con este ejemplo"><h3>Qué vas a aprender</h3><p>${esc(goal)}</p><h4>De dónde salen los valores</h4><p>${esc(origin)}</p><h4>Comprueba la cuenta actual</h4><p class="idea-equation">${esc(operation)}</p><p class="idea-table-note">Las cifras visibles están redondeadas; el cálculo conserva la precisión completa. Una suma escrita con esos decimales puede diferir ligeramente del resultado.</p><h4>Cómo se conecta y hasta dónde llega</h4><p>${esc(connection)}</p></section>`;
}

export function renderIdeaPlot(id,p,selected=0,sharedLossMax,plotId='idea-main'){
 const r=ideaResult(id,p);
 if(id==='prediction'){
  const a=axes({xmin:0,xmax:160,ymin:0,ymax:10,xlabel:'Fertilizante (kg/ha)',ylabel:'Rendimiento (t/ha)',xticks:[0,40,80,120,160],yticks:[0,2,4,6,8,10]});
  const body=a.body+line(a.x(0),a.y(p.bias),a.x(160),a.y(p.bias+160*p.slope),'class="idea-model-line"')+FARMS.map((f,i)=>pick(i,`Finca ${f.name}: ${f.x} kg/ha, observado ${fmt(f.y)}, predicción ${fmt(r.predicted[i])} t/ha`,line(a.x(f.x),a.y(f.y),a.x(f.x),a.y(r.predicted[i]),'class="idea-residual"')+dot(a.x(f.x),a.y(f.y),colors[0])+dot(a.x(f.x),a.y(r.predicted[i]),colors[1],4)+text(a.x(f.x)+13,a.y(f.y)-10,f.name),Number(selected)===i)).join('');
  return svg('Seis fincas, recta y distancias entre observado y predicho',body);
 }
 if(id==='alerts'){
  const a=axes({xmin:0,xmax:1,ymin:0,ymax:11,xlabel:'Puntuación de cada planta',ylabel:'Plantas',xticks:[0,.2,.4,.6,.8,1],yticks:[]});
  return svg('Puntuaciones fijas y umbral de alerta',a.body+`<rect x="${a.x(p.threshold)}" y="50" width="${a.x(1)-a.x(p.threshold)}" height="235" class="idea-alert-area"/>`+line(a.x(p.threshold),35,a.x(p.threshold),285,'class="idea-threshold"')+text(Math.max(145,Math.min(600,a.x(p.threshold))),24,`Umbral ${fmt(p.threshold)}`,'text-anchor="middle"')+r.rows.map((v,i)=>{const yy=65+i*22;return pick(i,`${v.name}: puntuación ${fmt(v.score)}, ${v.plague?'con plaga':'sana'}, ${v.alert?'alerta':'sin alerta'}`,text(65,yy+5,v.name,'text-anchor="end"')+(v.plague?`<path d="M${a.x(v.score)} ${yy-8}l8 16h-16z" fill="${colors[1]}"/>`:dot(a.x(v.score),yy,colors[0]))+(v.alert?`<circle cx="${a.x(v.score)}" cy="${yy}" r="12" class="idea-alert-ring"/>`:''),Number(selected)===i)}).join(''));
 }
 if(id==='missing'){
  const a=axes({xmin:0,xmax:4,ymin:0,ymax:1000,xlabel:'Estación · B es estimada',ylabel:'Lluvia (mm)',xticks:[],yticks:[0,200,400,600,800,1000]});
  const values=[p.rainA,r.estimate,p.rainC,p.rainD];
  const hatchId=esc(plotId)+'-hatch';
  return svg('Registros medidos y estimación de lluvia para B',`<defs><pattern id="${hatchId}" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8L8 0" stroke="${colors[1]}" stroke-width="3"/></pattern></defs>`+a.body+line(78,a.y(r.estimate),678,a.y(r.estimate),'class="idea-threshold"')+values.map((v,i)=>pick(i,`Estación ${'ABCD'[i]}: ${v} mm ${i===1?'estimados':'medidos'}`,`<rect x="${a.x(i+.5)-35}" y="${a.y(v)}" width="70" height="${285-a.y(v)}" fill="${i===1?'url(#'+hatchId+')':colors[0]}" stroke="${i===1?colors[1]:colors[0]}"/>`+text(a.x(i+.5),a.y(v)-12,`${v}${i===1?' *':''}`,'text-anchor="middle"')+text(a.x(i+.5),312,'ABCD'[i],'text-anchor="middle"'),Number(selected)===i)).join(''));
 }
 if(id==='signal'){
  const a=axes({xmin:-4,xmax:4,ymin:-1.5,ymax:4.5,xlabel:'Señal de entrada',ylabel:'Salida de la función',xticks:[-4,-2,0,2,4],yticks:[-1,0,1,2,3,4]});
  return svg('ReLU, sigmoid y tanh sobre los mismos ejes',a.body+line(a.x(p.signal),50,a.x(p.signal),285,'class="idea-guide-line"')+['relu','sigmoid','tanh'].map((type,i)=>{const points=Array.from({length:161},(_,j)=>{const v=-4+j*.05;return `${a.x(v)},${a.y(activation(v,type))}`;}).join(' ');return `<polyline points="${points}" fill="none" stroke="${colors[i]}" stroke-dasharray="${['none','9 5','2 5'][i]}" stroke-width="${p.function===type?4:2}" opacity="${p.function===type?1:.55}"/>`+dot(a.x(p.signal),a.y(activation(p.signal,type)),colors[i],p.function===type?9:5);}).join(''));
 }
 if(id==='adjustment'){
  const top=sharedLossMax||Math.max(40,...p.history,r.next?.loss||0)*1.12,min=sharedLossMax?3-Math.sqrt(top):Math.min(-3,...p.states,r.next?.theta??3)-.5,max=sharedLossMax?3+Math.sqrt(top):Math.max(9,...p.states,r.next?.theta??3)+.5;
  const a=axes({xmin:min,xmax:max,ymin:0,ymax:top,xlabel:'Valor del parámetro',ylabel:'Pérdida (θ − 3)²',xticks:max-min>30?wideTicks(min,max):[-2,0,3,6,9].filter(v=>v>=min&&v<=max),yticks:[0,top/2,top]});
  const curveMin=Math.max(min,3-Math.sqrt(top)),curveMax=Math.min(max,3+Math.sqrt(top));
  const curve=Array.from({length:121},(_,i)=>{const theta=curveMin+(curveMax-curveMin)*i/120;return `${a.x(theta)},${a.y((theta-3)**2)}`;}).join(' ');
  const preview=r.next?line(a.x(p.theta),a.y(r.loss),a.x(r.next.theta),a.y(r.next.loss),'class="idea-next-line"')+`<g class="idea-next-step" role="img" aria-label="Siguiente paso, aún sin aplicar: parámetro ${fmt(r.next.theta,3)}, pérdida ${fmt(r.next.loss,3)}"><circle cx="${a.x(r.next.theta)}" cy="${a.y(r.next.loss)}" r="11"/>${text(Math.min(600,Math.max(140,a.x(r.next.theta))),Math.max(24,a.y(r.next.loss)-23),'Siguiente · sin aplicar','text-anchor="middle"')}</g>`:'';
  return svg('Parábola de pérdida y estados visitados',a.body+`<polyline points="${curve}" fill="none" stroke="${colors[0]}" stroke-width="3"/>`+line(a.x(3),50,a.x(3),285,'class="idea-guide-line"')+preview+p.states.map((theta,i)=>pick(i,`Paso ${i}: parámetro ${fmt(theta)}, pérdida ${fmt(p.history[i])}`,(i?line(a.x(p.states[i-1]),a.y(p.history[i-1]),a.x(theta),a.y(p.history[i]),'class="idea-residual"'):'')+dot(a.x(theta),a.y(p.history[i]),colors[1],Number(selected)===i?9:5)+((Number(selected)===i||i===0&&Math.hypot(a.x(theta)-a.x(p.states[Number(selected)]??p.theta),a.y(p.history[i])-a.y(p.history[Number(selected)]??r.loss))>28)?text(a.x(theta)+10,a.y(p.history[i])-9,i):''),Number(selected)===i)).join(''));
 }
 if(id==='vision'){
  const fruits=[[120,160,40,53],[300,145,48,60],[495,163,35,45]];
  return svg('Misma imagen con etiqueta, cajas o máscaras',`<rect x="60" y="35" width="600" height="300" rx="10" class="idea-image-bg"/>`+fruits.map(([xx,yy,rx,ry],i)=>{const x=xx+60,y=yy+35;return pick(i,`Fruto ${i+1}: centro ${xx},${yy} píxeles`,`<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${p.task==='segmentation'?colors[i]:['#b5c78f','#c7aa76','#94b582'][i]}"/>`+(p.task==='detection'?`<rect x="${x-rx}" y="${y-ry}" width="${2*rx}" height="${2*ry}" class="idea-box"/>`:'')+(p.task!=='classification'?text(x,y-ry-12,`Fruto ${i+1}`,'text-anchor="middle"'):''),Number(selected)===i);}).join('')+(p.task==='classification'?`<rect x="218" y="55" width="285" height="35" rx="6" class="idea-image-label"/>${text(360,79,'Etiqueta: imagen con frutos','text-anchor="middle" class="idea-image-label-text"')}`:''));
 }
 if(id==='neighbors'){
  const scaled=p.scaled==='yes';
  if(!scaled){
   const a=axes({xmin:0,xmax:3000,ymin:0,ymax:7,xlabel:'Distancia numérica · mezcla km y kg',ylabel:'Envío',xticks:[0,1000,2000,3000],yticks:[],left:90,width:510});
   return svg('Envíos ordenados por la distancia numérica que decide su voto',a.body+r.ranked.map((v,index)=>{const i=SHIPMENTS.findIndex(s=>s.id===v.id),yy=65+index*34,votes=r.selected.includes(v);return pick(i,`Envío ${v.id}: distancia numérica ${fmt(v.distance,3)}; ${votes?'participa':'no participa'} en la votación`,text(72,yy+5,v.id,'text-anchor="end"')+`<rect x="90" y="${yy-11}" width="${Math.max(0,a.x(v.distance)-90)}" height="22" rx="4" fill="${colors[v.kind]}" opacity="${votes?1:.4}"/>`+dot(a.x(v.distance),yy,colors[v.kind],5)+text(a.x(v.distance)+11,yy+5,fmt(v.distance,1))+text(700,yy+5,votes?'✓ vota':'—','text-anchor="end"'),Number(selected)===i);}).join(''));
  }
  const extent=Math.max(2.5,Math.ceil(Math.max(...r.query.map(Math.abs),...r.ranked.flatMap(v=>v.xy).map(Math.abs))*1.15)),ticks=extent===2.5?[-2,-1,0,1,2]:[-extent,-Math.floor(extent/2),0,Math.floor(extent/2),extent];
  const a=axes({xmin:-extent,xmax:extent,ymin:-extent,ymax:extent,xlabel:'Distancia estandarizada',ylabel:'Carga estandarizada',xticks:ticks,yticks:ticks,width:400,height:400,left:150,bottom:450});
  return svg('Envíos históricos y consulta estandarizados, con la misma escala en ambos ejes',a.body+r.selected.map(v=>line(a.x(r.query[0]),a.y(r.query[1]),a.x(v.xy[0]),a.y(v.xy[1]),'class="idea-residual"')).join('')+r.ranked.map(v=>{const i=SHIPMENTS.findIndex(s=>s.id===v.id);return pick(i,`Envío ${v.id}: ${v.km} km, ${v.kg} kg, ${v.kind?'Extendido':'Estándar'}`,dot(a.x(v.xy[0]),a.y(v.xy[1]),colors[v.kind],9)+text(a.x(v.xy[0])+13,a.y(v.xy[1])-10,v.id),Number(selected)===i);}).join('')+`<path d="M${a.x(r.query[0])} ${a.y(r.query[1])-11}l11 11-11 11-11-11z" class="idea-query"/>`,520);
 }
 return '';
}

const range=(key,label,min,max,step,value)=>`<label class="idea-range" for="idea-${key}"><span>${label}<output data-output="${key}" for="idea-${key}"></output></span><input id="idea-${key}" data-control="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
const select=(key,label,options,value)=>`<label class="idea-select" for="idea-${key}">${label}<select id="idea-${key}" data-control="${key}">${options.map(([v,n])=>`<option value="${v}" ${v===value?'selected':''}>${n}</option>`).join('')}</select></label>`;
function controls(id,p){
 switch(id){
 case 'prediction':return range('slope','Inclinación (pendiente) · t/ha por kg/ha',.005,.05,.0001,p.slope)+range('bias','Valor en 0 kg/ha (intercepto) · t/ha',0,2,.01,p.bias)+'<button type="button" class="button small" data-fit>Ajustar recta con estos datos</button>';
 case 'alerts':return range('threshold','Umbral de alerta',0,1,.05,p.threshold);
 case 'missing':return ['A','C','D'].map(n=>range('rain'+n,'Lluvia de '+n+' · mm',100,900,50,p['rain'+n])).join('');
 case 'signal':return range('signal','Señal de entrada',-4,4,.1,p.signal)+select('function','Función destacada',[['relu','ReLU'],['sigmoid','Sigmoid'],['tanh','tanh']],p.function)+'<p class="idea-function-note" data-function-note></p>';
 case 'adjustment':return range('rate','Tasa de aprendizaje',.05,1.1,.05,p.rate)+'<button type="button" class="button small" data-step="1">Dar un paso</button><button type="button" class="button secondary small" data-step="5">Calcular cinco pasos</button><details class="idea-reading"><summary>Comparar tasas</summary><p>Cambiar la tasa conserva el punto actual. Reinicia para comparar desde −2.</p></details>';
 case 'vision':return select('task','Salida que necesitas',[['classification','Etiqueta global'],['detection','Cajas de objetos'],['segmentation','Máscaras de objetos']],p.task);
 case 'neighbors':return range('km','Distancia de la consulta · km',20,50,1,p.km)+range('kg','Carga de la consulta · kg',2500,5500,100,p.kg)+select('k','Vecinos que votan',[['1','1 vecino'],['3','3 vecinos'],['5','5 vecinos']],String(p.k))+select('scaled','Escala de las variables',[['no','Unidades originales'],['yes','Estandarizar con los históricos']],p.scaled);
 default:return select('filter','Filtro',[['horizontal','Horizontal: cambio entre filas'],['average','Promedio de nueve píxeles']],p.filter)+'';
 }
}
function pixelPlot(p,r){
 const max=Math.max(...r.map.flat().map(Math.abs),1e-12);
 const grid=(values,kind,label)=>`<section><h4>${label}</h4><div class="idea-pixels" style="--columns:${values[0].length}">${values.map((row,y)=>row.map((v,x)=>{const active=kind==='pixel'?y>=p.row&&y<p.row+3&&x>=p.column&&x<p.column+3:y===p.row&&x===p.column,shade=kind==='window'&&v!==0?`style="background:color-mix(in srgb, ${v<0?'#ac602d':'#507b3c'} ${Math.round(8+40*Math.abs(v)/max)}%, var(--paper));color:var(--ink)"`:'';return `<button type="button" data-${kind}="${y},${x}" aria-label="${kind==='pixel'?'Píxel':'Mapa'}, fila ${y+1}, columna ${x+1}, valor ${fmt(v,3)}${kind==='pixel'&&active?', dentro de la ventana seleccionada':''}" aria-pressed="${kind==='pixel'?v===1:active}" class="${active?'pixel-selected':''} ${kind==='pixel'&&v===1?'pixel-on':''}" ${shade}>${kind==='pixel'?v:fmt(v,2)}</button>`;}).join('')).join('')}</div></section>`;
 return `<div class="idea-pixel-panels">${grid(p.image,'pixel','1 · Imagen editable 5 × 5')}<section><h4>2 · Filtro 3 × 3</h4><div class="idea-kernel">${r.kernel.flat().map(v=>`<span>${p.filter==='average'?'1/9':v}</span>`).join('')}</div></section>${grid(r.map,'window','3 · Mapa 3 × 3')}</div><details class="idea-reading"><summary>Ver la cuenta de esta ventana</summary><p class="idea-equation">Ventana desde fila ${p.row+1}, columna ${p.column+1}. Suma de productos = ${r.products.flat().map(v=>fmt(v,3)).join(' + ')} = <b>${fmt(r.value,3)}</b>.</p></details>`;
}
function dataView(id,p,selected,filter){
 const r=ideaResult(id,p),b=(i,n)=>rowButton(i,n,selected);
 if(id==='prediction')return table(['Finca','Entrada kg/ha','Observado t/ha','Predicho t/ha','Error absoluto t/ha'],FARMS.map((v,i)=>[b(i,v.name),v.x,fmt(v.y),fmt(r.predicted[i]),fmt(r.errors[i])]),'Las seis observaciones y los cálculos de la recta');
 if(id==='alerts'){const rows=r.rows.flatMap((v,i)=>!filter||v.kind===filter?[[b(i,v.name),v.plague?'Con plaga':'Sana',fmt(v.score),v.alert?'Alerta':'Sin alerta',{tp:'Detección correcta',fp:'Falsa alerta',fn:'Omisión',tn:'Descarte correcto'}[v.kind]]]:[]);return rows.length?table(['Planta','Realidad','Puntuación','Decisión','Resultado'],rows,'Plantas de la casilla seleccionada o del conjunto completo'):'<p class="idea-empty">Con este umbral no hay plantas en la casilla seleccionada. Puedes elegir otra casilla o mostrar las diez plantas.</p>';}
 if(id==='missing')return table(['Estación','Registro original','Entrada preparada'],['A','B','C','D'].map((n,i)=>[b(i,n),i===1?'Sin registro':p['rain'+n]+' mm',(i===1?r.estimate:p['rain'+n])+' mm'+(i===1?' · estimado':' · medido')]),'Antes y después de completar la entrada de B');
 if(id==='signal')return table(['Entrada','ReLU','Sigmoid','tanh'],[-4,-2,0,2,4].map(v=>[`<button type="button" data-signal="${v}" aria-label="Usar entrada ${v}">${v}</button>`,...['relu','sigmoid','tanh'].map(t=>fmt(activation(v,t),3))]),'Las tres funciones sobre las mismas cinco entradas')+'<p class="idea-table-note">Con entrada x: ReLU = máximo entre 0 y x; sigmoid = 1 / (1 + e<sup>−x</sup>); tanh = (e<sup>x</sup> − e<sup>−x</sup>) / (e<sup>x</sup> + e<sup>−x</sup>). e ≈ 2,718 es una constante matemática. Para x = 0, e⁰ = 1: sigmoid = 1/2 y tanh = 0/2.</p>';
 if(id==='adjustment')return table(['Paso','Parámetro','Gradiente usado','Tasa aplicada','Actualización aplicada','Pérdida'],p.states.map((v,i)=>[b(i,i),fmt(v,3),i?fmt(2*(p.states[i-1]-3),3):'—',i?fmt(p.rates[i-1],2):'—',i?fmt(v-p.states[i-1],3):'Inicio',fmt(p.history[i],3)]),'Historial completo: cada fila conserva el ajuste que realmente ocurrió');
 if(id==='vision')return p.task==='classification'?table(['Salida','Alcance'],[['Imagen con frutos','Una etiqueta para toda la imagen, sin posiciones individuales']],'Resultado de clasificación'):table(['Objeto',p.task==='detection'?'Caja [x₁,y₁,x₂,y₂] · px':'Región del cuerpo visible'],[[b(0,'Fruto 1'),p.task==='detection'?'[80,107,160,213]':'Elipse: centro [120,160], radios 40 y 53 px'],[b(1,'Fruto 2'),p.task==='detection'?'[252,85,348,205]':'Elipse: centro [300,145], radios 48 y 60 px'],[b(2,'Fruto 3'),p.task==='detection'?'[460,118,530,208]':'Elipse: centro [495,163], radios 35 y 45 px']],'Coordenadas relativas a la imagen de 600 × 300 píxeles');
 if(id==='neighbors')return table(['Envío','Distancia km','Carga kg',...(p.scaled==='yes'?['Distancia z','Carga z']:[]),'Servicio conocido','Distancia a consulta','¿Vota?'],r.ranked.map(v=>[b(SHIPMENTS.findIndex(s=>s.id===v.id),v.id),v.km,v.kg,...(p.scaled==='yes'?v.xy.map(n=>fmt(n,3)):[]),v.kind?'Extendido':'Estándar',fmt(v.distance,3),r.selected.includes(v)?'Sí':'No']),p.scaled==='yes'?'Orden por distancia euclídea entre variables estandarizadas':'Orden por distancia euclídea usando los números en sus unidades originales')+(p.scaled==='yes'?`<p class="idea-table-note">z = (valor − media) / desviación. Históricos: distancia, media ${fmt(r.stats[0].mean,3)} km y desviación ${fmt(r.stats[0].sd,3)} km; carga, media ${fmt(r.stats[1].mean,3)} kg y desviación ${fmt(r.stats[1].sd,3)} kg. Consulta transformada: (${r.query.map(v=>fmt(v,3)).join('; ')}). La distancia es √[(diferencia en z de distancia)² + (diferencia en z de carga)²].</p>`:'<p class="idea-table-note">Distancia numérica = √[(km histórico − km consulta)² + (kg histórico − kg consulta)²]. Al mezclar escalas, la variable con diferencias numéricas mayores pesa más; este valor no es una distancia geográfica en km.</p>');
 return table(['Fila de ventana','Píxeles','Pesos','Productos'],r.products.map((row,i)=>[i+1,p.image[p.row+i].slice(p.column,p.column+3).join(', '),r.kernel[i].map(v=>p.filter==='average'?'1/9':v).join(', '),row.map(v=>fmt(v,3)).join(', ')]),'Los nueve productos que forman la celda seleccionada');
}
function detail(id,p,selected){
 const r=ideaResult(id,p),i=Number(selected)||0;
 switch(id){
 case 'prediction':{const f=FARMS[i]||FARMS[0];return `${f.name}: ${fmt(p.bias)} + ${fmt(p.slope,4)} × ${f.x} = ${fmt(r.predicted[i])} t/ha. Observado: ${fmt(f.y)}. Error: ${fmt(r.errors[i])} t/ha.`;}
 case 'alerts':{const v=r.rows[i]||r.rows[0],count=r.tp+r.fp;return `${v.name}: ${fmt(v.score)} ${v.alert?'≥':'<'} ${fmt(p.threshold)} → ${v.alert?'alerta':'sin alerta'}. Revisiones: ${count} para 4 cupos${count>4?` (${count-4} por encima)`:''}. Falsas alertas: ${r.fp}. Plantas con plaga sin alerta: ${r.fn}.`;}
 case 'missing':return `${'ABCD'[i]}: ${i===1?`sin medición → ${r.estimate} mm estimados`:`${p['rain'+'ABCD'[i]]} mm registrados en el ejemplo`}. Ordenados: ${r.ordered.join(' · ')} → mediana ${r.estimate} mm; media ${fmt(r.mean)} mm.`;
 case 'signal':return `Entrada ${fmt(p.signal)} → ReLU ${fmt(r.values[0].value,3)} · sigmoid ${fmt(r.values[1].value,3)} · tanh ${fmt(r.values[2].value,3)}.`;
 case 'adjustment':{const step=Math.min(i,p.states.length-1);return step?`Paso ${step}: ${fmt(p.states[step-1],3)} − ${fmt(p.rates[step-1])} × ${fmt(2*(p.states[step-1]-3),3)} = ${fmt(p.states[step],3)}. Pérdida ${fmt(p.history[step-1],3)} → ${fmt(p.history[step],3)}: ${p.history[step]>p.history[step-1]?'aumentó':'bajó o se mantuvo'}.${p.states.length>=16?' Completaste 15 pasos; reinicia para otra prueba.':''}`:'Inicio: parámetro −2. Pérdida: (−2 − 3)² = 25. Da un paso para seguir el ajuste.';}
 case 'vision':return {classification:'Una etiqueta para toda la imagen: no localiza ni cuenta cada fruto.',detection:`Fruto ${i+1}: caja [${['80, 107, 160, 213','252, 85, 348, 205','460, 118, 530, 208'][i]}] px = [izquierda, arriba, derecha, abajo]. Localiza el objeto e incluye parte del fondo.`,segmentation:`Fruto ${i+1}: la máscara delimita los píxeles de su cuerpo visible. El fondo de la caja queda fuera.`}[p.task];
 case 'neighbors':{const v=r.ranked.find(v=>v.id===SHIPMENTS[i]?.id)||r.ranked[0],dx=v.xy[0]-r.query[0],dy=v.xy[1]-r.query[1];return `Envío ${v.id}: distancia = √[(${fmt(dx,3)})² + (${fmt(dy,3)})²] = ${fmt(v.distance,3)}${p.scaled==='yes'?' en escala estandarizada':''}. ${r.selected.includes(v)?'Participa en la votación.':'Queda fuera de los '+p.k+' vecinos.'} Gana ${r.kind?'Extendido':'Estándar'} (${r.kind?r.votes:p.k-r.votes} de ${p.k} votos).`;}
 default:return `Ventana (${p.row+1}, ${p.column+1}) → suma ${fmt(r.value,3)}. Edita un píxel para ver qué celdas del mapa cambian.`;
 }
}
function summary(id,p){const r=ideaResult(id,p);switch(id){case 'prediction':return [['Error medio en estas fincas',fmt(r.mae,3)+' t/ha']];case 'alerts':return [['Revisiones · capacidad de 4',r.tp+r.fp+' de 10 plantas'],['Falsas alertas',r.fp],['Plagas sin alerta',r.fn]];case 'missing':return [['B estimada',r.estimate+' mm'],['Media conocida',fmt(r.mean)+' mm']];case 'signal':return r.values.map(v=>[v.type,fmt(v.value,3)]);case 'adjustment':return [['Parámetro',fmt(p.theta,3)],['Pérdida actual',fmt(r.loss,3)],['Pasos',r.steps]];case 'vision':return [['Salida',p.task==='classification'?'1 etiqueta':p.task==='detection'?'3 cajas':'3 máscaras']];case 'neighbors':return [['Servicio predicho',r.kind?'Extendido':'Estándar'],['Vecinos que votan',r.selected.map(v=>v.id).join(', ')]];default:return [['Celda elegida',`${p.row+1}, ${p.column+1}`],['Suma',fmt(r.value,3)]];}}

export function mountIdeaStudio(el,initial='prediction'){
 let topic=TOPICS.find(t=>t.id===initial)||TOPICS[0],p=initialIdea(topic.id),selected=0,before=null,caseIndex=0,filter=null,chartZoom=false;
 const q=s=>el.querySelector(s);
 function markCustom(task){caseIndex=-1;q('[data-task]').textContent=task;el.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed','false'));}
 function animateChange(mode='case'){
  if(document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const nodes=mode==='select'?el.querySelectorAll('.idea-pick.is-selected,.idea-confusion [aria-pressed=true]'):mode==='pixel'?el.querySelectorAll('.idea-pixels .pixel-selected'):mode==='compare'?[q('[data-comparison]')]:[q('[data-graph]'),q('[data-extra]')];
  for(const node of nodes){if(!node||typeof node.animate!=='function')continue;node.getAnimations().forEach(a=>a.cancel());node.animate(mode==='select'?[{opacity:.55},{opacity:1}]:mode==='pixel'?[{backgroundColor:'var(--selected)'},{backgroundColor:getComputedStyle(node).backgroundColor}]:[{opacity:.6,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,0,0,1)'});}
 }
 function build(){
  const id=topic.id,hasThree=!['neighbors','convolution'].includes(id);
  el.innerHTML=`<section class="idea-studio ${chartZoom?'charts-enlarged':''}"><header class="idea-toolbar"><span>Elige un tema para empezar</span><button type="button" class="button secondary small" data-project aria-pressed="${document.body.classList.contains('projecting')}">${document.body.classList.contains('projecting')?'Salir de proyección':'Vista para proyectar'}</button></header><nav class="idea-nav" aria-label="Elige un tema">${TOPICS.map(t=>`<button type="button" data-topic="${t.id}" aria-pressed="${t.id===id}">${esc(t.label)}</button>`).join('')}</nav><label class="idea-mobile-switch">Tema<select data-topic-switch>${TOPICS.map(t=>`<option value="${t.id}" ${t.id===id?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><div class="idea-intro"><span class="idea-simulation">Ejemplo simulado</span><h2 tabindex="-1">${esc(topic.title)}</h2><p class="idea-data-description" data-brief></p></div><div class="idea-cases" role="group" aria-label="Casos para comparar">${topic.cases.map(([label],i)=>`<button type="button" data-case="${i}" aria-pressed="${i===caseIndex}"><span>${i+1}</span>${esc(label)}</button>`).join('')}</div><p class="idea-task" data-task>${esc(topic.cases[caseIndex][1])}</p><div class="idea-workbench"><div class="idea-graph-panel"><div class="idea-graph-actions"><button type="button" class="idea-text-button" data-chart-zoom aria-pressed="${chartZoom}">${chartZoom?'Ver gráficos completos':'Ampliar gráficos y etiquetas'}</button></div><div data-graph class="idea-chart-scroll" tabindex="0" role="region" aria-label="Gráfico interactivo; desplázate horizontalmente si no cabe"></div><div data-extra${id==='adjustment'?' class="idea-chart-scroll" tabindex="0" role="region" aria-label="Pérdida por paso; desplazamiento horizontal"':''}></div><div class="idea-chart-legend" data-legend></div><p class="idea-chart-hint">El gráfico completo se adapta al espacio. Amplíalo para leer sus etiquetas y desplázate dentro del recuadro; los valores también están en «Ver datos y cálculos».</p><details class="idea-reading"><summary>Cómo leer el gráfico</summary><p>${esc(topic.read)}</p></details></div><aside class="idea-controls" aria-label="Controles del ejemplo"><h3>Cambia y observa</h3>${controls(id,p)}<button type="button" class="button secondary small" data-save>Fijar para comparar</button><button type="button" class="idea-text-button" data-reset>Reiniciar ejemplo</button><div data-metrics></div></aside></div><div class="idea-insight" role="status" aria-live="polite" data-insight></div><div data-teaching></div><details class="idea-data-section" data-table-details><summary>Ver datos y cálculos</summary><div class="idea-section-heading"><button type="button" class="idea-text-button" data-show-all hidden>Mostrar las diez plantas</button></div><div data-table></div><p class="idea-table-note">Las cuentas usan valores sin redondear; las cifras se muestran con decimales limitados.</p></details><section class="idea-compare" data-comparison hidden></section>${hasThree?'<details class="idea-three"><summary>Ver los mismos datos en una escena 3D</summary><div class="iso-stage"><div data-canvas></div><div class="iso-three-host" data-three></div></div></details>':''}<details class="idea-context"><summary>Contexto y alcance del ejemplo</summary><p>${esc(topic.context)}</p><p>${esc(topic.data)}</p><p>${esc(topic.limit)}</p></details><details class="idea-sources"><summary>Fuentes para profundizar</summary><p><a href="${topic.source}" target="_blank" rel="noopener noreferrer">Fundamento del concepto ↗</a></p><p>Otras exploraciones visuales: <a href="https://pair.withgoogle.com/explorables/" target="_blank" rel="noopener noreferrer">Google AI Explorables</a>, <a href="https://playground.tensorflow.org/" target="_blank" rel="noopener noreferrer">TensorFlow Playground</a>, <a href="https://setosa.io/ev/ordinary-least-squares-regression/" target="_blank" rel="noopener noreferrer">Explained Visually</a> y <a href="https://poloclub.github.io/cnn-explainer/" target="_blank" rel="noopener noreferrer">CNN Explainer</a>.</p></details></section>`;
  q('.idea-three')?.addEventListener('toggle',()=>{if(q('.idea-three').open)draw();});
  draw();
 }
 function draw(){
  const id=topic.id,r=ideaResult(id,p);
  q('[data-graph]').innerHTML=id==='convolution'?pixelPlot(p,r):renderIdeaPlot(id,p,selected);
  let extra='';
  if(id==='alerts')extra=`<div class="idea-confusion" role="group" aria-label="Selecciona un resultado para filtrar las plantas">${[['tp','Con plaga + alerta',r.tp],['fn','Con plaga + sin alerta',r.fn],['fp','Sana + alerta',r.fp],['tn','Sana + sin alerta',r.tn]].map(([key,label,value])=>`<button type="button" data-kind="${key}" aria-pressed="${filter===key}"><span>${label}</span><b>${value}</b></button>`).join('')}</div>`;
  if(id==='missing')extra=`<div class="idea-ordered" aria-label="Medidas ordenadas">${r.ordered.map((v,i)=>`<span class="${i===1?'is-median':''}">${v} mm${i===1?'<b>Mediana</b>':''}</span>`).join('')}</div>`;
  if(id==='adjustment'){
   const max=Math.max(25,...p.history,r.next?.loss||0)*1.1,a=axes({xmin:0,xmax:15,ymin:0,ymax:max,xlabel:'Número de paso',ylabel:'Pérdida',xticks:[0,5,10,15],yticks:[0,max/2,max]});
   extra=svg('Pérdida en cada paso calculado',a.body+`<polyline points="${p.history.map((v,i)=>`${a.x(i)},${a.y(v)}`).join(' ')}" fill="none" stroke="${colors[0]}" stroke-width="3"/>`+p.history.map((v,i)=>pick(i,`Paso ${i}: pérdida ${fmt(v,3)}`,dot(a.x(i),a.y(v),colors[1]),Number(selected)===i)).join('')+(r.next?line(a.x(p.history.length-1),a.y(r.loss),a.x(r.next.step),a.y(r.next.loss),'class="idea-next-line"')+`<circle cx="${a.x(r.next.step)}" cy="${a.y(r.next.loss)}" r="9" class="idea-next-dot"><title>Siguiente pérdida, sin aplicar: ${fmt(r.next.loss,3)}</title></circle>`:''));
  }
  q('[data-extra]').innerHTML=extra;
  q('[data-legend]').innerHTML={prediction:'● Verde: observado · Naranja: predicho · Segmento: error',alerts:'▲ Con plaga · ● Sana · Aro: alerta · Zona sombreada: puntuación ≥ umbral',missing:'Barra verde: medida · Barra rayada: estimación de B',signal:'Línea continua: ReLU · Discontinua: sigmoid · Punteada: tanh',adjustment:'Curva: pérdida de la función · Puntos: pasos aplicados · Círculo punteado: siguiente paso, aún sin aplicar',vision:'Coordenadas desde la esquina superior izquierda · Cuerpos de fruto dibujados',neighbors:p.scaled==='yes'?'Verde: Estándar · Terracota: Extendido · Rombo: envío nuevo · Igual escala en ambos ejes':'Barras: distancia numérica calculada · ✓: participa entre los k más cercanos · Verde: Estándar · Terracota: Extendido',convolution:'0: píxel oscuro · 1: píxel claro · Borde marcado: ventana o celda seleccionada'}[id];
  q('[data-brief]').textContent={prediction:'La recta estima el rendimiento a partir del fertilizante. Los puntos son 6 fincas simuladas.',alerts:'El umbral es la puntuación mínima para activar una alerta. Prueba con 10 plantas simuladas, 4 con plaga.',missing:'Falta la lluvia de B en este periodo. La mediana usa el valor central de las otras 3 estaciones para completar esa entrada.',signal:'Una activación transforma una señal numérica. Compara qué devuelven ReLU, sigmoid y tanh para la misma entrada.',adjustment:'Un parámetro es un número ajustable. Aquí empieza en −2; buscamos acercarlo a 3 reduciendo la pérdida (parámetro − 3)².',vision:'Una misma imagen permite tareas distintas: clasificar la imagen, localizar objetos o delimitar sus píxeles. Aquí usamos 3 frutos dibujados.',neighbors:`Predecimos un servicio por los ${p.k} envíos históricos más cercanos. Hay 6 envíos simulados: compara distancia en km y carga en kg.`,convolution:'Un filtro combina píxeles vecinos para destacar cambios en una imagen. Edita esta imagen de 5 × 5 y observa el mapa.'}[id];
  q('[data-table]').innerHTML=dataView(id,p,selected,filter);q('[data-insight]').textContent=detail(id,p,selected);q('[data-metrics]').innerHTML=metrics(summary(id,p));
  q('[data-teaching]').innerHTML=ideaTeaching(id,p,selected);
  q('[data-show-all]').hidden=!filter;
  if(id==='signal')q('[data-function-note]').textContent={relu:'ReLU: conserva las entradas positivas y convierte las negativas en 0.',sigmoid:'Sigmoid: transforma cualquier entrada en una salida entre 0 y 1.',tanh:'tanh: transforma cualquier entrada en una salida entre −1 y 1.'}[p.function];
  el.querySelectorAll('[data-control]').forEach(input=>{input.value=p[input.dataset.control];const out=q(`[data-output="${input.dataset.control}"]`);if(out){out.textContent=fmt(p[input.dataset.control],input.dataset.control==='slope'?4:input.step<1?2:0);input.setAttribute('aria-valuetext',out.textContent);}});
  el.querySelectorAll('[data-step]').forEach(b=>b.disabled=p.states.length>=16);
  if(q('.idea-three')?.open){q('[data-canvas]').innerHTML=renderIdeaPlot(id,p,selected,undefined,'idea-fallback');renderThreeScene(q('[data-three]'),id,p,index=>{selected=id==='adjustment'?p.states.length-1:index;draw();});}
  const comparison=q('[data-comparison]');comparison.hidden=!before;
  if(before){const sharedMax=id==='adjustment'?Math.max(40,...p.history,...before.history,ideaResult(id,p).next?.loss||0,ideaResult(id,before).next?.loss||0)*1.12:undefined;comparison.innerHTML=`<div class="idea-section-heading"><h3>Compara A y B</h3><button type="button" class="idea-text-button" data-clear>Quitar comparación</button></div><p>A queda fijo; los controles cambian B.</p><div class="idea-pair">${[[before,'A · Guardado'],[p,'B · Actual']].map(([state,label])=>`<article><h4>${label}</h4>${metrics(summary(id,state))}<div class="idea-chart-scroll" tabindex="0" role="region" aria-label="Gráfico ${label}; desplazamiento horizontal">${id==='convolution'?table(['Fila','Mapa'],ideaResult(id,state).map.map((row,i)=>[i+1,row.map(v=>fmt(v,2)).join(' · ')]),'Mapa de respuestas'):renderIdeaPlot(id,state,selected,sharedMax,label.startsWith('A')?'idea-comparison-a':'idea-comparison-b')}</div></article>`).join('')}</div>`;
   comparison.querySelectorAll('[data-pick]').forEach(node=>{node.removeAttribute('role');node.removeAttribute('tabindex');node.removeAttribute('aria-pressed');node.removeAttribute('data-pick');});
  }
 }
 function changeControl(e){
  if(e.target.hasAttribute('data-topic-switch')){const next=TOPICS.find(t=>t.id===e.target.value);if(!next||next.id===topic.id)return;topic=next;p=initialIdea(topic.id);selected=0;before=null;filter=null;caseIndex=0;build();q('.idea-intro h2').focus();animateChange();return;}
  const key=e.target.dataset.control;if(!key)return;
  const value=e.target.tagName==='SELECT'&&key!=='k'?e.target.value:Number(e.target.value);if(p[key]===value)return;p[key]=value;
  markCustom({prediction:'Los puntos observados no cambian. Ajusta la recta y compara sus errores.',alerts:'Las puntuaciones no cambian. Compara revisiones, falsas alertas y plagas sin alerta.',missing:'B sigue sin una medición. Compara cómo cambian la mediana y la media.',signal:'Sigue la misma entrada hasta cada curva y compara sus salidas.',adjustment:'El círculo punteado anticipa el próximo paso con esta tasa. El historial cambia al pulsar Dar un paso.',vision:'La imagen permanece igual. Cambia la salida que necesita el trabajo.',neighbors:'Selecciona un envío para comprobar su distancia y si participa en la votación.',convolution:'Selecciona una celda del mapa para ver qué ventana y qué productos la generan.'}[topic.id]);
  if(topic.id==='adjustment')selected=p.states.length-1;draw();
 }
 el.addEventListener('input',changeControl);el.addEventListener('change',changeControl);
 el.addEventListener('click',e=>{
  const target=e.target.closest('button,[data-pick]');if(!target)return;
  if(target.dataset.topic){topic=TOPICS.find(t=>t.id===target.dataset.topic);p=initialIdea(topic.id);selected=0;before=null;filter=null;caseIndex=0;build();q('.idea-intro h2').focus();animateChange();}
  else if(target.dataset.case!==undefined){caseIndex=Number(target.dataset.case);p=ideaCase(topic.id,caseIndex);selected=0;filter=null;q('[data-task]').textContent=topic.cases[caseIndex][1];el.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));draw();animateChange();}
  else if(target.dataset.pick!==undefined){const origin=target.closest('[data-table],[data-extra],[data-canvas],[data-graph]')||q('[data-graph]');selected=Number(target.dataset.pick);draw();origin.querySelector(`[data-pick="${selected}"]`)?.focus({preventScroll:true});animateChange('select');}
  else if(target.dataset.kind){filter=filter===target.dataset.kind?null:target.dataset.kind;draw();q('[data-table-details]').open=true;q(`[data-kind="${target.dataset.kind}"]`)?.focus({preventScroll:true});animateChange('select');}
  else if(target.hasAttribute('data-show-all')){filter=null;draw();}
  else if(target.hasAttribute('data-fit')){p=ideaCase('prediction',2);caseIndex=2;q('[data-task]').textContent=topic.cases[2][1];el.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case==='2')));draw();animateChange();}
  else if(target.dataset.step){p=stepIdea(p,Number(target.dataset.step));selected=p.states.length-1;draw();animateChange('select');}
  else if(target.hasAttribute('data-signal')){p.signal=Number(target.dataset.signal);caseIndex=-1;q('[data-task]').textContent='Compara las tres salidas para la entrada elegida.';el.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed','false'));draw();q(`[data-signal="${p.signal}"]`)?.focus({preventScroll:true});animateChange();}
  else if(target.hasAttribute('data-reset')){p=initialIdea(topic.id);selected=0;filter=null;before=null;caseIndex=0;build();q('[data-reset]').focus({preventScroll:true});}
  else if(target.hasAttribute('data-save')){before=structuredClone(p);q('[data-save]').textContent='Actualizar comparación';draw();animateChange('compare');}
  else if(target.hasAttribute('data-clear')){before=null;q('[data-save]').textContent='Fijar para comparar';draw();}
  else if(target.hasAttribute('data-chart-zoom')){chartZoom=!chartZoom;q('.idea-studio').classList.toggle('charts-enlarged',chartZoom);target.setAttribute('aria-pressed',String(chartZoom));target.textContent=chartZoom?'Ver gráficos completos':'Ampliar gráficos y etiquetas';}
  else if(target.dataset.pixel){const [row,column]=target.dataset.pixel.split(',').map(Number);p.image[row][column]=1-p.image[row][column];markCustom('La imagen cambió: selecciona una celda del mapa para seguir su ventana y sus productos.');draw();q(`[data-pixel="${row},${column}"]`).focus({preventScroll:true});animateChange('pixel');}
  else if(target.dataset.window){[p.row,p.column]=target.dataset.window.split(',').map(Number);draw();q(`[data-window="${p.row},${p.column}"]`).focus({preventScroll:true});animateChange('pixel');}
  else if(target.hasAttribute('data-project')){document.body.classList.toggle('projecting');target.setAttribute('aria-pressed',String(document.body.classList.contains('projecting')));target.textContent=document.body.classList.contains('projecting')?'Salir de proyección':'Vista para proyectar';}
 });
 el.addEventListener('keydown',e=>{if(e.target.matches('[data-pick]')&&e.target.tagName.toLowerCase()!=='button'&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 build();
}
